    private func fe(_ l: [UInt64]) -> Fe { Fe(l[0], l[1], l[2], l[3]) }
    private func bytes(_ hex: String) -> [UInt8] {
        var out: [UInt8] = []
        var i = hex.startIndex
        while i < hex.endIndex { let j = hex.index(i, offsetBy: 2); out.append(UInt8(hex[i..<j], radix: 16)!); i = j }
        return out
    }

    func testFieldOperationsMatchBigIntegers() {
        XCTAssertGreaterThan(Self.field.count, 100)
        for (a, b, sum, diff, prod) in Self.field {
            XCTAssertEqual(T.fadd(fe(a), fe(b)), fe(sum), "add \(a) \(b)")
            XCTAssertEqual(T.fsub(fe(a), fe(b)), fe(diff), "sub \(a) \(b)")
            XCTAssertEqual(T.fmul(fe(a), fe(b)), fe(prod), "mul \(a) \(b)")
            XCTAssertEqual(T.fmul(fe(b), fe(a)), fe(prod), "mul commutes \(a) \(b)")
        }
    }

    func testPrimeOrderClassification() {
        XCTAssertGreaterThan(Self.points.count, 80)
        for (h, want, kind) in Self.points {
            XCTAssertEqual(T.isPrimeOrder(bytes(h)), want, "\(kind) \(h)")
            XCTAssertEqual(T.isPrimeOrder(bytes(h)), want, "(cached) \(kind) \(h)")
        }
    }
